#!/usr/bin/env python3
"""Keep the pinned SMS sound bank address space for a native score interpreter."""
from pathlib import Path
import hashlib,json,re
ROOT=Path(__file__).resolve().parents[1]
SHA='9e324e92bd833b45126861b6f1d2dcbb51251bdf3df6d563ab3a3ff784d8cf88'
def main():
 rom=(ROOT/'upstream/ps1disasm/ps1original.sms').read_bytes()
 assert hashlib.sha256(rom).hexdigest()==SHA
 symbols={n:int(a,16) for b,a,n in re.findall(r'^(\w+):(\w+) (\S+)$',(ROOT/'build/sms-reference/ps1built.sym').read_text(),re.M) if b=='0c'}
 for name,addr in {'Snd_UpdateAll':0x8043,'LABEL_B12_823F':0x823f,'LABEL_B12_8253':0x8253,'LABEL_B12_827B':0x827b,'LABEL_B12_82DB':0x82db,'LABEL_B12_8874':0x8874,'LABEL_B12_A877':0xa877,'LABEL_B12_A916':0xa916}.items():assert symbols[name]==addr,(name,symbols[name])
 data=rom[12*16384:13*16384]
 (ROOT/'src/audio_data.h').write_text('/* Generated immutable source sound-bank address space. */\n#ifndef PS_AUDIO_DATA_H\n#define PS_AUDIO_DATA_H\n#include <stdint.h>\n#define AUDIO_DATA_BANK 61u\nextern const uint8_t audio_data[16384],audio_low0[16384],audio_low1[16384];\nextern const uint16_t audio_apu_period[2][1024];\nextern const uint8_t audio_apu_noise[1024],audio_apu_fixed_noise[3],audio_enemy_sfx[74];\n#endif\n')
 (ROOT/'src/audio_data.c').write_text('/* Generated by tools/extract_audio.py; source SHA256 '+SHA+'. */\n#ifdef __SDCC\n#pragma bank 61\n#endif\n#include "audio_data.h"\nconst uint8_t audio_data[16384]={\n'+',\n'.join(','.join('0x%02x'%v for v in data[i:i+16]) for i in range(0,len(data),16))+'\n};\n')
 for low in range(2):
  block=rom[low*16384:(low+1)*16384]
  (ROOT/f'src/audio_low_{62+low}.c').write_text(f'/* Source fixed ROM alias reads used by SFX pitch modulation. */\n#ifdef __SDCC\n#pragma bank {62+low}\n#endif\n#include "audio_data.h"\nconst uint8_t audio_low{low}[16384]={{\n'+',\n'.join(','.join('0x%02x'%v for v in block[i:i+16]) for i in range(0,len(block),16))+'\n};\n')
 periods=[[2048-((divider*(2097152 if wave else 4194304)+3579545//2)//3579545) for divider in range(1024)] for wave in range(2)]
 def noise(target):
  choices=[(abs(524288/(d or .5)/2**(s+1)-target),(s<<4)|d) for s in range(14) for d in range(8)]
  return min(choices)[1]
 table=[noise(3579545/(32*(d or 1))) for d in range(1024)]
 fixed=[noise(3579545/(512<<d)) for d in range(3)]
 visual=int(re.search(r'^03:(\w+) LABEL_B03_8FC7$',(ROOT/'build/sms-reference/ps1built.sym').read_text(),re.M)[1],16)
 enemies=int(re.search(r'^03:(\w+) B03_EnemyData$',(ROOT/'build/sms-reference/ps1built.sym').read_text(),re.M)[1],16)
 enemy_sfx=[rom[3*16384+(visual&16383)+24*(rom[3*16384+(enemies&16383)+32*i+19]-1)+23] for i in range(1,75)]
 (ROOT/'src/audio_tables.c').write_text('/* Generated nearest GBC periods for NTSC SMS3579545Hz clock; bank15. */\n#ifdef __SDCC\n#pragma bank 15\n#endif\n#include "audio_data.h"\nconst uint16_t audio_apu_period[2][1024]={\n'+',\n'.join('{'+','.join(map(str,row))+'}' for row in periods)+'};\nconst uint8_t audio_apu_noise[1024]={'+','.join(map(str,table))+'};\nconst uint8_t audio_apu_fixed_noise[3]={'+','.join(map(str,fixed))+'};\nconst uint8_t audio_enemy_sfx[74]={'+','.join(map(str,enemy_sfx))+'};\n')
 report={'source_sha256':SHA,'source_bank':12,'native_banks':[61,62,63],'bytes':49152,'sound_bank_sha256':hashlib.sha256(data).hexdigest(),'fixed_rom_alias_sha256':hashlib.sha256(rom[:32768]).hexdigest(),'conversion_table_bytes':5123,'music_commands':[hex(i) for i in range(0x81,0x95)],'effect_commands':[hex(i) for i in range(0xa0,0xd5)],'control_commands':[hex(i) for i in range(0xd5,0xda)],'source_symbol_addresses_checked':True}
 (ROOT/'build/audio_extraction.json').write_text(json.dumps(report,indent=2)+'\n')
 print('Preserved 49,152 source bytes for score parsing and authentic fixed-ROM aliases; no SMS CPU emulation in the cartridge.')
if __name__=='__main__':main()
